declare(strict_types=1);ini_set('session.save_path',__DIR__.'/../includes/runtime');set_time_limit(0);require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/gemini_transport.php';if(PHP_SAPI!=='cli')exit(1);$orders=[1,3,4,5];$file=__DIR__.'/data/grade6-history-lessons1-3-5.json';$out=[];if(is_file($file)){$old=json_decode((string)file_get_contents($file),true);if(is_array($old))$out=$old;}$rows=db()->query("SELECT l.display_order,l.title_si,l.content_si FROM lessons l JOIN grades g ON g.id=l.grade_id JOIN subjects s ON s.id=l.subject_id WHERE g.grade_number=6 AND s.name_en='History' AND l.medium='Sinhala' AND l.status='active' AND l.display_order IN(1,3,4,5) ORDER BY l.display_order")->fetch_all(MYSQLI_ASSOC);if(count($rows)!==4)throw new RuntimeException('Selected History lessons were not found.');foreach($rows as $row){$key=(string)$row['display_order'];if(count($out[$key]['questions']??[])===30){echo "Skipped lesson $key\n";continue;}$data=null;for($attempt=1;$attempt<=5&&!$data;$attempt++){$prompt="ශ්‍රී ලංකා 6 ශ්‍රේණිය ඉතිහාසය සිංහල මාධ්‍ය පාඩම සඳහා පහත පෙළපොත් අන්තර්ගතය පමණක් පදනම් කරගෙන පැහැදිලි සිංහල Unicode MCQ හරියටම 30ක් සාදන්න. ප්‍රධාන ඓතිහාසික කරුණු, මූලාශ්‍ර, කාල අනුපිළිවෙළ, පුද්ගලයන්, ස්ථාන සහ සිදුවීම් සමබරව ආවරණය කරන්න. එකම ප්‍රශ්නය නැවත නොදෙන්න. JSON array එක පමණක් දෙන්න. සෑම object එකකම question,a,b,c,d,correct,explanation keys තිබිය යුතුය; correct අගය a/b/c/d එකකි. පාඩම {$row['display_order']}: {$row['title_si']}\n\n{$row['content_si']}";$payload=json_encode(['contents'=>[['parts'=>[['text'=>$prompt]]]],'generationConfig'=>['temperature'=>0.05,'maxOutputTokens'=>18000,'responseMimeType'=>'application/json']],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$r=gemini_http_json(GEMINI_API_BASE.rawurlencode(GEMINI_MODEL).':generateContent?key='.rawurlencode(GEMINI_API_KEY),['Content-Type: application/json'],$payload);if($r['status']!==200)continue;$body=json_decode($r['body'],true);$text='';foreach($body['candidates'][0]['content']['parts']??[] as $part)$text.=$part['text']??'';$candidate=json_decode($text,true);if(is_array($candidate)&&count($candidate)===30)$data=$candidate;}if(!$data)throw new RuntimeException("Lesson $key failed.");foreach($data as $q){if(!in_array($q['correct']??'',['a','b','c','d'],true))throw new RuntimeException('Invalid answer key.');foreach(['question','a','b','c','d','explanation'] as $field)if(trim((string)($q[$field]??''))==='')throw new RuntimeException("Missing $field.");}$out[$key]=['title'=>$row['title_si'],'questions'=>$data];ksort($out,SORT_NUMERIC);if(!is_dir(dirname($file)))mkdir(dirname($file),0775,true);file_put_contents($file,json_encode($out,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));echo "Built lesson $key\n";}echo 'Frozen '.count($out)." lesson sets.\n";
